using Word = int; // Standard processor word size (e.g., 32-bit)

enum class SrcSelect : uint8_t {
    REG_A,
    REG_B,
    ALU_OUT,
    MEM_DATA
};

// MUX used for selecting data written back to the Register File
Word WriteBack_MUX(Word A, Word B, Word C, Word D,
                   SrcSelect Control_Signal) {
    switch (Control_Signal) {
        case SrcSelect::REG_A:   return A;
        case SrcSelect::REG_B:   return B;
        case SrcSelect::ALU_OUT: return C;
        case SrcSelect::MEM_DATA:return D;
        default:                 return 0; // Error/Halt
    }
}

